class TaskManager extends EventEmitter {
  constructor() {
    super();
    this.tasks = new Map();
  }

  addTask(task) {
    const id = Date.now().toString();
    this.tasks.set(id, task);
    this.emit('task:added', { id, task });
    return id;
  }

  completeTask(id) {
    const task = this.tasks.get(id);
    if (task) {
      task.status = 'completed';
      this.emit('task:completed', { id, task });
    }
  }
}

// Usage:
